/**
 * The Worker's entry: answers the requests that need no Next.js itself and
 * hands everything else to OpenNext.
 *
 * On the free Workers plan a request gets 10 ms of CPU. Going through Next.js
 * costs 3-14 ms before any page code runs, while an image from KV or the
 * one-row query behind /api/latest-post take well under 1 ms here.
 *
 * `next dev` never runs this file: there app/media/[...key]/route.ts and
 * app/api/latest-post/route.ts answer the same paths.
 */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import openNext from "./.open-next/worker.js";
import { LATEST_POST_SQL, toSummary, type PostRow } from "./lib/blog/rows";
import { isMediaKey, mediaNotFound, mediaResponse, readMedia, type MediaStore } from "./lib/media-response";

interface D1 {
  prepare(sql: string): { bind(...values: unknown[]): { first<T>(): Promise<T | null> } };
}

interface Context {
  waitUntil(promise: Promise<unknown>): void;
}

interface PageCache {
  list(options: { prefix: string; cursor?: string }): Promise<{
    keys: { name: string }[];
    list_complete: boolean;
    cursor?: string;
  }>;
  delete(key: string): Promise<void>;
}

type Env = { MEDIA: MediaStore; DB: D1; NEXT_INC_CACHE_KV: PageCache; ADMIN_CODE?: string };

type Handler = { fetch(request: Request, env: Env, ctx: Context): Promise<Response> };

const next = openNext as Handler;

const MEDIA_PREFIX = "/media/";

/**
 * How far back each run of the hourly cron (wrangler.jsonc) looks for posts
 * that came out. Wider than the interval, so a run that fails is made up for
 * by the next ones.
 */
const SCHEDULE_LOOKBACK_MS = 3 * 60 * 60 * 1000;

/** Where OpenNext keeps rendered pages in KV: `incremental-cache/<build id>/<hash>.cache`. */
const PAGE_CACHE_PREFIX = "incremental-cache/";

/**
 * Old pages removed per cron run. The free plan allows 1000 KV deletes a day;
 * 40 an hour stays under that and clears a deploy's leftovers within hours.
 */
const PAGE_CACHE_DELETES_PER_RUN = 40;

export default {
  async fetch(request: Request, env: Env, ctx: Context): Promise<Response> {
    const { pathname } = new URL(request.url);
    const read = request.method === "GET" || request.method === "HEAD";

    if (read && pathname.startsWith(MEDIA_PREFIX)) return serveMedia(pathname, request.method, env);
    if (read && pathname === "/api/latest-post") return latestPost(env);

    return next.fetch(request, env, ctx);
  },

  async scheduled(_controller: unknown, env: Env, ctx: Context) {
    // Each job stands on its own: one failing does not hold up the other.
    const results = await Promise.allSettled([publishScheduledPosts(env, ctx), removeOldPages(env)]);
    const failed = results.find((result) => result.status === "rejected");

    if (failed) throw failed.reason;
  },
};

/**
 * Cached post pages only change when /admin marks them stale. A post dated in
 * the future needs no save when its time comes, so this marks them stale once
 * it is out.
 */
async function publishScheduledPosts(env: Env, ctx: Context) {
  const now = Date.now();
  const due = await env.DB.prepare(
    "SELECT 1 AS due FROM posts WHERE status = 'publish' AND published_at > ? AND published_at <= ? LIMIT 1",
  )
    .bind(new Date(now - SCHEDULE_LOOKBACK_MS).toISOString(), new Date(now).toISOString())
    .first();

  if (!due) return;
  if (!env.ADMIN_CODE) throw new Error("ADMIN_CODE is not set, so the blog cache cannot be revalidated.");

  // Through Next.js, so the stale marks are written exactly as a save in /admin writes them.
  const request = new Request("https://worker.internal/api/admin/revalidate", {
    method: "POST",
    headers: { Authorization: `Bearer ${env.ADMIN_CODE}` },
  });
  const response = await next.fetch(request, env, ctx);

  if (!response.ok) throw new Error(`Revalidating the blog cache failed: ${response.status}`);
}

/**
 * Cache keys carry the build id, so every deploy starts an empty cache and
 * leaves the previous build's pages behind in KV, where nothing reads them.
 * Those are removed a few at a time.
 */
async function removeOldPages(env: Env) {
  // Set by OpenNext's routing module when the Worker starts.
  const buildId = process.env.OPEN_NEXT_BUILD_ID;

  // Without the current build id every page would look old.
  if (!buildId) throw new Error("OPEN_NEXT_BUILD_ID is not set, so old cached pages cannot be told apart.");

  const current = `${PAGE_CACHE_PREFIX}${buildId}/`;
  const old: string[] = [];
  let cursor: string | undefined;

  do {
    const page = await env.NEXT_INC_CACHE_KV.list({ prefix: PAGE_CACHE_PREFIX, cursor });

    for (const { name } of page.keys) if (!name.startsWith(current)) old.push(name);

    cursor = page.list_complete ? undefined : page.cursor;
  } while (cursor && old.length < PAGE_CACHE_DELETES_PER_RUN);

  await Promise.all(old.slice(0, PAGE_CACHE_DELETES_PER_RUN).map((key) => env.NEXT_INC_CACHE_KV.delete(key)));
}

async function serveMedia(pathname: string, method: string, env: Env) {
  let key: string;

  try {
    key = decodeURIComponent(pathname.slice(MEDIA_PREFIX.length));
  } catch {
    return mediaNotFound();
  }

  if (!isMediaKey(key)) return mediaNotFound();

  const object = await readMedia(env.MEDIA, key);

  if (!object) return mediaNotFound();

  if (method === "HEAD") {
    await object.body.cancel();

    return mediaResponse(null, object.type);
  }

  return mediaResponse(object.body, object.type);
}

async function latestPost(env: Env) {
  const headers = { "Cache-Control": "no-store" };

  try {
    const row = await env.DB.prepare(LATEST_POST_SQL).bind(new Date().toISOString()).first<PostRow>();

    return Response.json({ post: row && toSummary(row) }, { headers });
  } catch (error) {
    console.error("Loading the latest post failed:", error);

    // The home page tries again, then leaves the section out.
    return new Response(null, { status: 503, headers });
  }
}
